workspace "Hospital Appointment System" "A minimal C4 model of a hospital appointment system" {

    person {
        patient = person "Patient" "A patient who books and manages hospital appointments."
    }

    softwareSystems {
        appointmentSystem = softwareSystem "Appointment System" "Allows patients to book and manage hospital appointments." {
            containers {
                bookingWebApp = container "Booking Web App" "Web application used by patients to book and view appointments." "Web"
                schedulingService = container "Scheduling Service" "Manages appointment slots and schedules." "Service"
            }
        }
    }

    relationships {
        patient -> bookingWebApp "Books and views appointments" "Browser"
        bookingWebApp -> schedulingService "Reserves appointment slots" "REST/HTTPS"
    }

    views {
        systemContext "Appointment System" "SystemContext" "Shows the Patient interacting with the Appointment System." {
            include *
        }
    }
}

